local E = require "ejoysdk_lua.ejoysdk"
local V = require "ejoysdk_lua.version"
local JSON = require 'ejoysdk_lua.ejoysdk_json'
local EM = require "ejoysdk_lua.ejoysdk_module"

local TAG = EM.MODULE.PROTOCAL .. 'ejoysdk_lx_protocal'

-- SDK Identifier，SDK标识码。
-- 网游：在SDK客户端第一次初始化时，向SDK服务端请求获取si，并存储在SDK客户端，作为SDK客户端每次请求服务时的标识。SDK服务端根据特定的算法生成此si，具有唯一性、加密性。 如果SDK客户端存储的si信息被删除，则需重新初始化，请求新的si。
-- 单机：由SDK客户端在游戏首次安装或全新覆盖安装时生成。 如果SDK客户端存储的ci信息被删除，则需重新生成ci。
-- 例：si=ef8bdf-29396-bjfdifuk-8762901-abc8790
local lx_si

local M = {}

M.ENV = {
    DEBUG = 'debug',
    RELEASE = 'release'
}

M.URL_BASE = {
    GW_ACCOUNT = 'https://magic-account.flysdk.cn/client/'
}

M.URL_BASE_DEBUG = {
    GW_ACCOUNT = 'http://magic-account.game.alibaba.net/client/'
}

M.SERVICE = {
    REALNAME_INFO_REPORT = 'realname.info.report'
}

local SERVICE_MAPPING = {
    [M.SERVICE.REALNAME_INFO_REPORT] = 'GW_ACCOUNT'
}

-- 403-灵犀android网游
-- 404-灵犀iOS网游
M.APPID = {
    FOR_LX_IOS = '404',
    FOR_LX_ANROID = '403'
}

local l_env = M.ENV.RELEASE

local function get_url(api)
    local url_base
    local server = SERVICE_MAPPING[api]
    if l_env == M.ENV.RELEASE then
        url_base = M.URL_BASE[server]
    else
        url_base = M.URL_BASE_DEBUG[server]
    end

    local url = nil
    if url_base then
        --例子：http://collect.flysdk.cn/client/log.collect.commonlog?ver=1.0&df=ra&cver=3.8.3.9&os=android
        local aligames = require 'ejoysdk_lua.vendors.aligames'
        local ft_version = aligames.get_ft_version()
        if ft_version == '' then
            ft_version = '1.0.0'
        end
        url = url_base .. api .. '?ver=1.0&df=json&gt=ng&cver='..ft_version..'&os='..E.Sysinfo.os()
    end

    return url
end

local function get_request_id()
    math.randomseed(os.time())
    local random_mills = math.random(1, 1000)
    local sys_clock = os.time() * 1000
    local random_time_in_mills = sys_clock + random_mills
    E.LOG.debug(TAG, 'get_request_id :'.. tostring(random_time_in_mills) .. ', sys_clock:'.. tostring(sys_clock) ..', random_mills:'.. tostring(random_mills))
    return random_time_in_mills
end

local function get_request_client()
    -- collect client info
    local client = {}
    client.si = lx_si
    client.ve = V.LUA_VERSION
    client.os = E.Sysinfo.os()

    local pkg_info = E.get_pkg_info()
    client.ex = {}
    client.ex.model = E.Sysinfo.model()
    client.ex.net = E.Sysinfo.network_type()
    client.ex.resX = E.Sysinfo.screen().width
    client.ex.resY = E.Sysinfo.screen().height
    client.ex.utdid = pkg_info.utdid
    client.ex.luaVersion = V.LUA_VERSION
    local product_code = E.CONFIG.get_config('product')
    if product_code and product_code ~= '' then
        client.ex.productCode = product_code:lower()
    end

    if client.os == 'android' then
        client.fr = client.os .. ' ' .. E.Sysinfo.os_version()
        client.appId = M.APPID.FOR_LX_ANROID
        client.ex.imei = pkg_info.imei
        client.ex.mf = E.Sysinfo.get_manufacturer()
        client.ex.osId = E.Sysinfo.android_id()
    elseif client.os == 'ios' then
        client.fr = E.Sysinfo.machine()
        client.appId = M.APPID.FOR_LX_IOS
        client.ex.idfa = E.Sysinfo.idfa()
        client.ex.uniqueid = E.Sysinfo.uuid()
        client.ex.sysinfo_ejoy_ext_info = E.Sysinfo.sysinfo_ejoy_ext_info()
    end

    return client
end

local function get_request_game()
    local pkg_info = E.get_pkg_info()
    --collect game info
    local game = {}
    game.gameId = pkg_info.game_id
    game.channelId = 'DG_2'
    if pkg_info.ds_sub_channel_id and pkg_info.ds_sub_channel_id ~= '' then
        game.channelId = pkg_info.ds_sub_channel_id
    end

    local gdp = require 'ejoysdk_lua.gangplank_data_provider'
    local player_info = gdp.PLAYER_INFO.get()
    if player_info then
        game.roleId = player_info.player_id
        game.zoneId = player_info.server_id
    end

    return game
end

local function get_lx_body(params)
    local id = get_request_id()
    local client = get_request_client()
    local game = get_request_game()

    local body = {}
    body.id = id
    body.game = game
    body.client = client
    body.data = params
    return body
end

local function get_request_params()
    return {
        trace = true
    }
end

function M.set_si(si)
    if si then
        E.LOG.debug(TAG, 'set_si success: '.. tostring(si))
        lx_si = si
    else
        E.LOG.warn(TAG, 'set_si failed for si is nil')
    end

end

function M.set_env(env)
    l_env = env
end

function M.post(api, params, cb)
    local url = get_url(api)
    E.LOG.debug(TAG, 'post url:'..url)

    local lx_body = get_lx_body(params)
    --E.LOG.debug(TAG, 'post body>>')
    --E.log(lx_body)
    local request_params = get_request_params()
    E.HTTP.post(url, request_params, E.HTTP.CT_JSON, lx_body, function(resp)
        --E.LOG.debug(TAG, 'post response>>, url:'..url)
        --E.log(resp)
        if resp.status == 200 then
            local body_json = JSON.decode(resp.body)
            E.log(body_json)
            if body_json.state.code == 1 then
                --E.LOG.debug(TAG, 'post response succ, url:'..url)
                cb(true, body_json.data)
            else
                --E.LOG.warn(TAG, 'post response failed, url:'..url..', code:'..body_json.state.code..', msg:'..body_json.state.msg)
                cb(false, body_json.state.code, body_json.state.msg)
            end
        else
            --E.LOG.warn(TAG, 'post response failed, url:'..url..', status:'..resp.status)
            cb(false, resp.status, '请求出错')
        end
    end)
end

return M